public interface SyncrLibraryInterface {
    
    fun `authorId`(): kotlin.String
    
    fun `createNote`(`request`: CreateNoteRequest): Receipt
    
    /**
     * Registers an (empty) notebook. Idempotent when it already exists.
     */
