/**
 * @suppress
 */
public object FfiConverterTypeSyncrLibrary: FfiConverter<SyncrLibrary, Long> {
    override fun lower(value: SyncrLibrary): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): SyncrLibrary {
        return SyncrLibrary(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): SyncrLibrary {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: SyncrLibrary) = 8UL

    override fun write(value: SyncrLibrary, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



