sealed class Base {
    
    object Absent : Base()
    
    
    data class Operation(
        val `operationId`: kotlin.String) : Base()
        
    {
        

        companion object
    }
    
    data class Confirmed(
        val `revision`: kotlin.ULong) : Base()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBase : FfiConverterRustBuffer<Base>{
    override fun read(buf: ByteBuffer): Base {
        return when(buf.getInt()) {
            1 -> Base.Absent
            2 -> Base.Operation(
                FfiConverterString.read(buf),
                )
            3 -> Base.Confirmed(
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Base): ULong = when(value) {
        is Base.Absent -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Base.Operation -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`operationId`)
            )
        }
        is Base.Confirmed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`revision`)
            )
        }
    }

    override fun write(value: Base, buf: ByteBuffer) {
        when(value) {
            is Base.Absent -> {
                buf.putInt(1)
                Unit
            }
            is Base.Operation -> {
                buf.putInt(2)
                FfiConverterString.write(value.`operationId`, buf)
                Unit
            }
            is Base.Confirmed -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`revision`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






