    }
    
    object ResyncRequired : ChangePage()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeChangePage : FfiConverterRustBuffer<ChangePage>{
    override fun read(buf: ByteBuffer): ChangePage {
        return when(buf.getInt()) {
            1 -> ChangePage.Events(
                FfiConverterSequenceTypeChangeEvent.read(buf),
                FfiConverterTypeEventCursor.read(buf),
                FfiConverterBoolean.read(buf),
                )
            2 -> ChangePage.ResyncRequired
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ChangePage): ULong = when(value) {
        is ChangePage.Events -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeChangeEvent.allocationSize(value.`items`)
                + FfiConverterTypeEventCursor.allocationSize(value.`nextCursor`)
                + FfiConverterBoolean.allocationSize(value.`hasMore`)
            )
        }
        is ChangePage.ResyncRequired -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: ChangePage, buf: ByteBuffer) {
        when(value) {
            is ChangePage.Events -> {
                buf.putInt(1)
                FfiConverterSequenceTypeChangeEvent.write(value.`items`, buf)
                FfiConverterTypeEventCursor.write(value.`nextCursor`, buf)
                FfiConverterBoolean.write(value.`hasMore`, buf)
                Unit
            }
            is ChangePage.ResyncRequired -> {
                buf.putInt(2)
