                4UL
            )
        }
        is OperationLookup.Committed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeReceipt.allocationSize(value.`receipt`)
            )
        }
    }

    override fun write(value: OperationLookup, buf: ByteBuffer) {
        when(value) {
            is OperationLookup.NotRecorded -> {
                buf.putInt(1)
                Unit
            }
            is OperationLookup.Committed -> {
                buf.putInt(2)
                FfiConverterTypeReceipt.write(value.`receipt`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






